import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long k = nextLong();
        int n = s.length(), left = 0, answer = 0;
        long groups = 0; // runs of '0' inside the window; each needs one flip
        for (int right = 0; right < n; right++) {
            if (s.charAt(right) == '0' && (right == 0 || s.charAt(right - 1) == '1')) groups++;
            while (groups > k) {
                if (s.charAt(left) == '0' && (left == right || s.charAt(left + 1) == '1')) groups--;
                left++;
            }
            answer = Math.max(answer, right - left + 1);
        }
        System.out.println(answer);
    }
}

